"use client";

import { type AnchorHTMLAttributes, type HTMLAttributes, type ReactNode, type Ref, useEffect, useRef } from "react";
import { useProximity } from "../interaction/hooks";
import type { ProximityOptions } from "../interaction/proximity";
import { cx } from "../utils/cx";
import { Slot } from "../utils/slot";

export type DockProps = Omit<HTMLAttributes<HTMLElement>, "children"> & {
  /** Names the navigation landmark ("Studio sections"). Required: a page may have several navs. */
  "aria-label": string;
  /** Brand or home link pinned to the top of the dock (see DockBrand). */
  brand?: ReactNode;
  /** The edge a `fixed` dock sits on. A right dock mirrors the layout and measures the pointer from its right edge. Default `left`. */
  side?: "left" | "right";
  /** `fixed` pins the dock to the viewport's left edge (an app sidebar); `inline` keeps it in flow (demos, panels). */
  placement?: "fixed" | "inline";
  /** Tunes the magnification (reach, range, smoothing...). Read once per mount. */
  proximity?: ProximityOptions;
  ref?: Ref<HTMLElement>;
  children: ReactNode;
};

/**
 * The Holominimal sidebar: transparent, integrated with the page, and spatially responsive. The current entry is the
 * largest and brightest; entries near a mouse pointer swell and brighten; distant ones recede. Touch devices, keyboard
 * users and reduced motion get the same hierarchy without the magnification (focus still lifts the focused entry).
 * Below 860px the dock becomes a conventional top strip.
 */
export function Dock({
  brand,
  placement = "fixed",
  side = "left",
  proximity,
  className,
  ref,
  children,
  ...rest
}: DockProps) {
  const own = useRef<HTMLElement>(null);
  useProximity(own, { itemSelector: "[data-hm-dock-item]", edge: side === "right" ? "end" : "start", ...proximity });
  // as a scrolling strip (small screens), keep the current entry in view after navigation
  useEffect(() => {
    const el = own.current;
    if (!el || el.scrollWidth <= el.clientWidth) return;
    const current = el.querySelector<HTMLElement>('[data-hm-dock-item][aria-current="page"]');
    if (current) el.scrollTo({ left: current.offsetLeft - el.clientWidth / 2 + current.offsetWidth / 2 });
  });
  return (
    <nav
      {...rest}
      ref={(node) => {
        own.current = node;
        if (typeof ref === "function") return ref(node);
        if (ref) (ref as { current: HTMLElement | null }).current = node;
      }}
      className={cx("hm-dock", className)}
      data-placement={placement}
      data-side={side === "right" ? "right" : undefined}
    >
      {brand ? <div className="hm-dock-brand">{brand}</div> : null}
      <ul className="hm-dock-list">{children}</ul>
    </nav>
  );
}

type LinkProps = AnchorHTMLAttributes<HTMLAnchorElement> & {
  /** Render your router's link instead of <a>: `<DockItem asChild current><Link href="/x">X</Link></DockItem>`. */
  asChild?: boolean;
  ref?: Ref<HTMLAnchorElement>;
};

export type DockItemProps = LinkProps & {
  /** This entry is the current page (sets aria-current="page"). Exactly one entry should be current. */
  current?: boolean;
  /** Pages under this entry, usually only for the current one (see DockSubnav). */
  subnav?: ReactNode;
};

export function DockItem({ current, subnav, asChild, className, children, ...rest }: DockItemProps) {
  const Comp = asChild ? Slot : "a";
  return (
    <li className="hm-dock-entry">
      <Comp
        {...(rest as object)}
        data-hm-dock-item=""
        className={cx("hm-dock-item", className)}
        aria-current={current ? "page" : undefined}
      >
        {children}
      </Comp>
      {subnav}
    </li>
  );
}

export function DockBrand({ asChild, className, ...rest }: LinkProps) {
  const Comp = asChild ? Slot : "a";
  return <Comp {...(rest as object)} className={cx("hm-dock-brand-link", className)} />;
}

export type DockSubnavProps = HTMLAttributes<HTMLUListElement> & { "aria-label": string };

/** The current section's pages, listed under its entry so nothing is hidden behind a click. */
export function DockSubnav({ className, ...rest }: DockSubnavProps) {
  return <ul {...rest} className={cx("hm-dock-sub", className)} />;
}

export function DockSubItem({ current, asChild, className, ...rest }: LinkProps & { current?: boolean }) {
  const Comp = asChild ? Slot : "a";
  return (
    <li>
      <Comp
        {...(rest as object)}
        className={cx("hm-dock-sub-item", className)}
        aria-current={current ? "page" : undefined}
      />
    </li>
  );
}
